#!/usr/bin/env python3
"""v2-26: New look (Evergreen/Ivory theme, Light/Dark/System setting). Run from the nutrismart project folder. Safe to run twice.
OFF until you switch on 'ui_new_design'. No screen is rewritten; colours are re-pointed only while the switch is on."""
import base64, os, sys
if not os.path.isdir('src') or not os.path.isdir('functions'):
    sys.exit('Run this inside the nutrismart project folder (cd ~/Downloads/nutrismart).')
def rd(p): return open(p, encoding='utf8').read()
def wr(p, s):
    os.makedirs(os.path.dirname(p) or '.', exist_ok=True); open(p, 'w', encoding='utf8').write(s)
def sub(p, old, new, marker):
    s = rd(p)
    if marker in s: print('already applied:', p); return
    if old not in s: sys.exit(f'Cannot find the expected text in {p}. Stop and send this message to Claude.')
    wr(p, s.replace(old, new, 1)); print('updated', p)
def append(p, text, marker):
    s = rd(p)
    if marker in s: print('already applied:', p); return
    wr(p, s.rstrip('\n') + '\n' + text); print('updated', p)
NEW = {
  'src/components/theme/ThemeHost.tsx': '',
  'src/components/theme/AppearanceCard.tsx': '',
  'src/styles/newdesign.css': '',
  'src/tests/ui26/newdesign.test.ts': '',
  'src/lib/theme.ts': '',
  'supabase/migrations/047_ui_new_design.sql': '',
  'docs/NEW_DESIGN.md': '',
}
for p, b in NEW.items():
    wr(p, base64.b64decode(b).decode('utf8')); print('wrote', p)

sub('src/pages/AppShell.tsx', "import FeedbackPrompts              from '../components/FeedbackPrompts';", "import FeedbackPrompts              from '../components/FeedbackPrompts';\nimport { ThemeHost } from '../components/theme/ThemeHost';", "import { ThemeHost }")
sub('src/pages/AppShell.tsx', "      <FeedbackPrompts />", "      <ThemeHost />\n      <FeedbackPrompts />", "<ThemeHost />")
sub('src/pages/tabs/ProfileTab.tsx', "import { useFlag } from '../../lib/useFlag';", "import { useFlag } from '../../lib/useFlag';\nimport { AppearanceCard } from '../../components/theme/AppearanceCard';", "import { AppearanceCard }")
sub('src/pages/tabs/ProfileTab.tsx', "        {/* Sign out */}", "        <AppearanceCard />\n\n        {/* Sign out */}", "<AppearanceCard />")

s = rd('src/tests/v2/BlueprintContract.test.ts')
for old in ('45', '46'):
    if f'says {old} migrations' in s:
        wr('src/tests/v2/BlueprintContract.test.ts', s.replace(f'says {old} migrations', 'says 47 migrations').replace(f'expect(n).toBe({old})', 'expect(n).toBe(47)')); print('updated BlueprintContract'); break
append('docs/PROGRESS.md', "\n## New look (migration 047)\nEvergreen/Ivory theme with Light, Dark and Same-as-phone, behind the switch ui_new_design (off by default). See docs/NEW_DESIGN.md. Per-screen layout changes come next.\n", 'New look (migration 047)')
print('\nDone. Next: run supabase/migrations/047_ui_new_design.sql in Supabase, then commit and push.')
